"""Investigation exports: structured case data (JSON), transaction summary (CSV) and the PDF report.

The PDF keeps three kinds of statements visibly separate:
  * Automated indicators (rule alerts) and model predictions (anomaly scores) - generated by software;
  * Investigator observations (notes) and conclusions (findings) - recorded by people;
  * Limitations.
"""
from __future__ import annotations

import csv
import io
from collections import Counter
from datetime import datetime

import matplotlib

matplotlib.use("Agg")
import matplotlib.dates as mdates  # noqa: E402
import matplotlib.pyplot as plt  # noqa: E402
import networkx as nx  # noqa: E402
from reportlab.lib import colors  # noqa: E402
from reportlab.lib.enums import TA_LEFT  # noqa: E402
from reportlab.lib.pagesizes import A4  # noqa: E402
from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet  # noqa: E402
from reportlab.lib.units import mm  # noqa: E402
from reportlab.platypus import (Image, KeepTogether, Paragraph, SimpleDocTemplate, Spacer, Table,  # noqa: E402
                                TableStyle)
from sqlalchemy import or_, select  # noqa: E402
from sqlalchemy.orm import Session  # noqa: E402
from xml.sax.saxutils import escape  # noqa: E402

from app.core.timeutil import as_utc  # noqa: E402
from app.detection.rules import PATTERN_LABELS  # noqa: E402
from app.models import (Account, Alert, Case, CaseAccount, CaseEvent, CaseFinding, CaseNote, CaseTransaction,  # noqa: E402
                        DetectionRun, Entity, Evidence, Transaction, utcnow)
from app.services.evidence import verify_chain  # noqa: E402
from app.services.graph import latest_run_id  # noqa: E402

STATUS_LABEL = {"open": "Open", "under_investigation": "Under Investigation", "pending_review": "Pending Review",
                "closed": "Closed", "escalated": "Escalated"}


def _iso(dt):
    return as_utc(dt).isoformat() if dt else None


def collect_case_data(db: Session, case: Case) -> dict:
    accts = db.scalars(select(CaseAccount).where(CaseAccount.case_id == case.id)).all()
    acct_ids = [ca.account_id for ca in accts]
    ctx = db.scalars(select(CaseTransaction).where(CaseTransaction.case_id == case.id)).all()
    txn_ids = [c.transaction_id for c in ctx]
    txns = db.scalars(select(Transaction).where(Transaction.id.in_(txn_ids)).order_by(Transaction.timestamp)).all() if txn_ids else []
    all_acct_ids = set(acct_ids) | {t.sender_account_id for t in txns} | {t.receiver_account_id for t in txns}
    acct_map = {a.id: a for a in db.scalars(select(Account).where(Account.id.in_(all_acct_ids)))} if all_acct_ids else {}
    ent_ids = {a.entity_id for a in acct_map.values() if a.entity_id}
    ents = {e.id: e for e in db.scalars(select(Entity).where(Entity.id.in_(ent_ids)))} if ent_ids else {}
    run_id = latest_run_id(db)
    run = db.get(DetectionRun, run_id) if run_id else None
    alerts = db.scalars(select(Alert).where(Alert.run_id == run_id, Alert.account_id.in_(acct_ids)).order_by(Alert.score.desc())).all() if run_id and acct_ids else []
    evidence = db.scalars(select(Evidence).where(Evidence.case_id == case.id).order_by(Evidence.uploaded_at)).all()
    notes = db.scalars(select(CaseNote).where(CaseNote.case_id == case.id).order_by(CaseNote.created_at)).all()
    findings = db.scalars(select(CaseFinding).where(CaseFinding.case_id == case.id).order_by(CaseFinding.created_at)).all()
    events = db.scalars(select(CaseEvent).where(CaseEvent.case_id == case.id).order_by(CaseEvent.created_at)).all()

    def acct_dict(a: Account):
        e = ents.get(a.entity_id)
        return {"account_id": a.id, "account_number": a.account_number, "holder": a.holder_name, "bank": a.bank,
                "entity_id": a.entity_id, "entity_type": e.entity_type if e else None, "risk_score": a.risk_score,
                "risk_level": a.risk_level, "patterns": a.patterns, "txn_count": a.txn_count,
                "total_in": float(a.total_in or 0), "total_out": float(a.total_out or 0),
                "first_seen": _iso(a.first_seen), "last_seen": _iso(a.last_seen)}

    return {
        "case": {"id": case.id, "case_number": case.case_number, "title": case.title, "summary": case.summary,
                 "objectives": case.objectives, "status": case.status, "priority": case.priority,
                 "created_at": _iso(case.created_at), "updated_at": _iso(case.updated_at), "closed_at": _iso(case.closed_at),
                 "created_by": case.created_by.full_name if case.created_by else None,
                 "assignees": [u.full_name for u in case.assignees]},
        "subject_accounts": [{**acct_dict(acct_map[ca.account_id]), "case_role": ca.role, "note": ca.note} for ca in accts if ca.account_id in acct_map],
        "entities": [{"entity_id": e.id, "name": e.name, "entity_type": e.entity_type, "risk_score": e.risk_score,
                      "aliases": (e.attributes or {}).get("aliases", [])} for e in ents.values()],
        "transactions": [{"id": t.id, "txn_id": t.txn_id, "timestamp": _iso(t.timestamp),
                          "sender_account": acct_map[t.sender_account_id].account_number, "sender_name": t.sender_name,
                          "receiver_account": acct_map[t.receiver_account_id].account_number, "receiver_name": t.receiver_name,
                          "amount": float(t.amount), "currency": t.currency, "type": t.txn_type, "reference": t.reference,
                          "status": t.status, "risk_score": t.risk_score, "risk_level": t.risk_level, "flagged": t.is_flagged,
                          "patterns": t.patterns, "anomaly_percentile": t.anomaly_score} for t in txns],
        "automated_indicators": [{"alert_id": a.id, "kind": a.kind, "pattern": a.pattern, "pattern_label": PATTERN_LABELS.get(a.pattern, a.pattern),
                                  "severity": a.severity, "confidence": a.confidence, "score": a.score, "title": a.title,
                                  "reasons": a.reasons, "review_status": a.review_status, "account_id": a.account_id,
                                  "total_amount": float(a.total_amount or 0), "first_txn_at": _iso(a.first_txn_at),
                                  "last_txn_at": _iso(a.last_txn_at)} for a in alerts],
        "detection_run": {"id": run.id, "completed_at": _iso(run.completed_at), "params": run.params} if run else None,
        "evidence": [{"evidence_code": e.evidence_code, "filename": e.original_filename, "file_type": e.file_type,
                      "category": e.category, "sha256": e.sha256, "size_bytes": e.size_bytes, "description": e.description,
                      "uploaded_at": _iso(e.uploaded_at), "uploaded_by": e.uploaded_by.full_name if e.uploaded_by else None,
                      "verification_status": e.verification_status, "last_verified_at": _iso(e.last_verified_at),
                      "custody_chain": verify_chain(db, e)} for e in evidence],
        "investigator_notes": [{"author": n.author.full_name if n.author else None, "created_at": _iso(n.created_at), "body": n.body} for n in notes],
        "investigator_findings": [{"title": f.title, "description": f.description, "status": f.status,
                                   "author": f.author.full_name if f.author else None, "created_at": _iso(f.created_at),
                                   "related_alert_ids": f.related_alert_ids} for f in findings],
        "case_events": [{"type": e.event_type, "description": e.description, "created_at": _iso(e.created_at),
                         "actor": e.actor.full_name if e.actor else None} for e in events],
        "generated_at": utcnow().isoformat(),
    }


def transactions_csv(data: dict) -> bytes:
    buf = io.StringIO()
    cols = ["txn_id", "timestamp", "sender_account", "sender_name", "receiver_account", "receiver_name", "amount", "currency",
            "type", "reference", "status", "risk_score", "risk_level", "flagged", "patterns", "anomaly_percentile"]
    w = csv.DictWriter(buf, fieldnames=cols, extrasaction="ignore")
    w.writeheader()
    for t in data["transactions"]:
        w.writerow({**t, "patterns": ";".join(t["patterns"] or [])})
    return buf.getvalue().encode()


# ------------------------------------------------------------------ figures
RISK_COLORS = {"critical": "#dc2626", "high": "#ea580c", "medium": "#d97706", "low": "#64748b"}


def network_figure(data: dict) -> bytes | None:
    if not data["transactions"]:
        return None
    G = nx.DiGraph()
    labels, subjects = {}, {a["account_number"] for a in data["subject_accounts"]}
    for t in data["transactions"]:
        s, r = t["sender_account"], t["receiver_account"]
        labels[s], labels[r] = t["sender_name"] or s, t["receiver_name"] or r
        if G.has_edge(s, r):
            G[s][r]["amount"] += t["amount"]; G[s][r]["n"] += 1
        else:
            G.add_edge(s, r, amount=t["amount"], n=1, flagged=t["flagged"])
    fig, ax = plt.subplots(figsize=(7.2, 5.0), dpi=150)
    pos = nx.kamada_kawai_layout(G) if len(G) <= 60 else nx.spring_layout(G, seed=1)
    nx.draw_networkx_nodes(G, pos, ax=ax, node_size=[520 if n in subjects else 260 for n in G],
                           node_color=["#b91c1c" if n in subjects else "#475569" for n in G], linewidths=0.8, edgecolors="#0f172a")
    widths = [0.8 + 2.5 * (d["amount"] / max(x["amount"] for *_, x in G.edges(data=True))) for *_, d in G.edges(data=True)]
    nx.draw_networkx_edges(G, pos, ax=ax, width=widths, edge_color=["#dc2626" if d["flagged"] else "#94a3b8" for *_, d in G.edges(data=True)],
                           arrows=True, arrowsize=12, connectionstyle="arc3,rad=0.08", node_size=420)
    label_pos = {k: (v[0], v[1] - 0.07) for k, v in pos.items()}  # place labels below the markers
    nx.draw_networkx_labels(G, label_pos, {n: (labels[n][:22]) for n in G}, font_size=6.5, ax=ax, verticalalignment="top",
                            bbox={"boxstyle": "round,pad=0.15", "fc": "white", "ec": "none", "alpha": 0.75})
    ax.margins(0.12)
    if len(G.edges) <= 25:
        nx.draw_networkx_edge_labels(G, pos, {(u, v): f"${d['amount']:,.0f}" for u, v, d in G.edges(data=True)}, font_size=5.5, ax=ax,
                                     rotate=False, bbox={"boxstyle": "round,pad=0.1", "fc": "white", "ec": "none", "alpha": 0.8})
    ax.set_axis_off()
    ax.set_title("Case transactions - subject accounts in red; flagged transfers in red", fontsize=8)
    buf = io.BytesIO()
    fig.tight_layout()
    fig.savefig(buf, format="png")
    plt.close(fig)
    return buf.getvalue()


def timeline_figure(data: dict) -> bytes | None:
    if not data["transactions"]:
        return None
    ts = [datetime.fromisoformat(t["timestamp"]) for t in data["transactions"]]
    amts = [t["amount"] for t in data["transactions"]]
    cols = [RISK_COLORS.get(t["risk_level"], "#64748b") for t in data["transactions"]]
    fig, ax = plt.subplots(figsize=(7.2, 2.6), dpi=150)
    ax.scatter(ts, amts, c=cols, s=18, edgecolors="#0f172a", linewidths=0.3, zorder=3)
    ax.vlines(ts, 0, amts, colors=cols, linewidth=0.6, alpha=0.6)
    ax.set_ylabel("Amount (USD)", fontsize=7)
    ax.tick_params(labelsize=6.5)
    loc = mdates.AutoDateLocator(minticks=3, maxticks=8)
    ax.xaxis.set_major_locator(loc)
    ax.xaxis.set_major_formatter(mdates.ConciseDateFormatter(loc))
    ax.yaxis.set_major_formatter(matplotlib.ticker.FuncFormatter(lambda v, _: f"${v:,.0f}"))
    ax.grid(alpha=0.25)
    ax.set_title("Case transactions over time (colour = automated risk level)", fontsize=8)
    fig.tight_layout()
    buf = io.BytesIO()
    fig.savefig(buf, format="png")
    plt.close(fig)
    return buf.getvalue()


# ------------------------------------------------------------------ PDF
def _styles():
    ss = getSampleStyleSheet()
    base = ParagraphStyle("b", parent=ss["BodyText"], fontName="Helvetica", fontSize=8.8, leading=12, alignment=TA_LEFT)
    return {
        "title": ParagraphStyle("t", parent=ss["Title"], fontName="Helvetica-Bold", fontSize=17, leading=21, spaceAfter=4),
        "h1": ParagraphStyle("h1", parent=ss["Heading2"], fontName="Helvetica-Bold", fontSize=11.5, spaceBefore=10, spaceAfter=4,
                             textColor=colors.HexColor("#0f172a")),
        "h2": ParagraphStyle("h2", parent=ss["Heading3"], fontName="Helvetica-Bold", fontSize=9.5, spaceBefore=6, spaceAfter=2),
        "body": base,
        "small": ParagraphStyle("s", parent=base, fontSize=7.5, leading=9.5, textColor=colors.HexColor("#334155")),
        "cell": ParagraphStyle("c", parent=base, fontSize=7.2, leading=8.8),
        "banner": ParagraphStyle("bn", parent=base, fontSize=8, leading=10.5, textColor=colors.HexColor("#7c2d12"),
                                 backColor=colors.HexColor("#ffedd5"), borderPadding=5, borderColor=colors.HexColor("#fdba74"), borderWidth=0.5),
    }


def _table(rows, widths, st, header_bg="#1e293b"):
    data = [[c if isinstance(c, Paragraph) else Paragraph(escape(str(c)).replace("\n", "<br/>"), st["cell"]) for c in r] for r in rows]
    t = Table(data, colWidths=widths, repeatRows=1)
    t.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor(header_bg)), ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
        ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"), ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("GRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#cbd5e1")),
        ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#f8fafc")]),
        ("LEFTPADDING", (0, 0), (-1, -1), 3), ("RIGHTPADDING", (0, 0), (-1, -1), 3),
    ]))
    return t


def _header_rows(rows, st):
    return [[Paragraph(f"<font color='white'><b>{escape(c)}</b></font>", st["cell"]) for c in rows[0]], *rows[1:]]


def build_pdf(data: dict, generated_by: str) -> bytes:
    st = _styles()
    buf = io.BytesIO()
    c = data["case"]
    doc = SimpleDocTemplate(buf, pagesize=A4, leftMargin=16 * mm, rightMargin=16 * mm, topMargin=18 * mm, bottomMargin=16 * mm,
                            title=f"Investigation report {c['case_number']}", author=generated_by)
    W = doc.width
    gen = data["generated_at"]

    def on_page(canvas, d):
        canvas.saveState()
        canvas.setFont("Helvetica", 7)
        canvas.setFillColor(colors.HexColor("#64748b"))
        canvas.drawString(16 * mm, 10 * mm, f"{c['case_number']} · CONFIDENTIAL - investigation material · generated {gen[:19]}Z")
        canvas.drawRightString(A4[0] - 16 * mm, 10 * mm, f"Page {d.page}")
        canvas.restoreState()

    s = []
    p = lambda txt, style="body": s.append(Paragraph(txt, st[style]))  # noqa: E731
    esc = lambda v: escape(str(v)) if v not in (None, "") else "—"  # noqa: E731
    p("Financial Investigation Report", "title")
    p(f"<b>Investigation ID:</b> {esc(c['case_number'])} &nbsp;&nbsp; <b>Status:</b> {esc(STATUS_LABEL.get(c['status'], c['status']))} "
      f"&nbsp;&nbsp; <b>Priority:</b> {esc(c['priority'])}")
    p(f"<b>Title:</b> {esc(c['title'])}")
    p(f"<b>Opened:</b> {esc((c['created_at'] or '')[:19])} by {esc(c['created_by'])} &nbsp;&nbsp; <b>Assigned:</b> {esc(', '.join(c['assignees']))}")
    p(f"<b>Report generated:</b> {esc(gen[:19])} UTC by {esc(generated_by)}")
    s.append(Spacer(1, 6))
    p("This report distinguishes <b>automated indicators</b> (rule-based alerts), <b>model predictions</b> (statistical anomaly "
      "scores) and <b>investigator conclusions</b>. Automated indicators and model predictions identify activity that "
      "<i>may</i> warrant review; they are not proof of wrongdoing. Only Section 11 records conclusions reached by investigators.", "banner")

    p("1. Case summary", "h1"); p(esc(c["summary"]).replace("\n", "<br/>"))
    p("2. Investigation objectives", "h1"); p(esc(c["objectives"]).replace("\n", "<br/>"))

    p("3. Entities and accounts involved", "h1")
    rows = [["Account", "Holder", "Type", "Bank", "Case role", "Txns", "In / Out (USD)", "Auto risk"]]
    for a in data["subject_accounts"]:
        rows.append([a["account_number"], a["holder"] or "—", a["entity_type"] or "—", a["bank"] or "—", a["case_role"], a["txn_count"],
                     f"{a['total_in']:,.0f} / {a['total_out']:,.0f}", f"{a['risk_score']:.0f} ({a['risk_level']})"])
    s.append(_table(_header_rows(rows, st), [26 * mm, 32 * mm, 16 * mm, 26 * mm, 17 * mm, 10 * mm, 26 * mm, 18 * mm], st)) if len(rows) > 1 else p("No accounts added to the case.")
    aliases = [e for e in data["entities"] if e["aliases"]]
    if aliases:
        p("Entities with investigator-verified aliases: " + "; ".join(f"{esc(e['name'])} (aka {esc(', '.join(e['aliases']))})" for e in aliases), "small")

    p("4. Suspicious transactions", "h1")
    tx = data["transactions"]
    if tx:
        total = sum(t["amount"] for t in tx)
        p(f"{len(tx)} transactions associated with the case, total value ${total:,.2f}; {sum(1 for t in tx if t['flagged'])} were flagged by automated detection.")
        rows = [["Date (UTC)", "Txn ID", "From", "To", "Amount", "Auto risk", "Indicators"]]
        for t in tx[:150]:
            rows.append([t["timestamp"][:16].replace("T", " "), t["txn_id"], f"{t['sender_name'] or ''}\n{t['sender_account']}",
                         f"{t['receiver_name'] or ''}\n{t['receiver_account']}", f"${t['amount']:,.2f}",
                         f"{t['risk_score']:.0f}", ", ".join(PATTERN_LABELS.get(x, x).split(" (")[0] for x in t["patterns"]) or "—"])
        s.append(_table(_header_rows(rows, st), [24 * mm, 20 * mm, 32 * mm, 32 * mm, 20 * mm, 13 * mm, 37 * mm], st))
        if len(tx) > 150:
            p(f"Table truncated to 150 of {len(tx)} transactions; the full list is in the CSV export.", "small")
    else:
        p("No transactions have been associated with this case.")

    p("5. Detection methodology", "h1")
    run = data["detection_run"]
    p("Automated detection combines explainable rules (structuring/smurfing, rapid pass-through movement, temporal circular flows, "
      "high velocity, dormant-account reactivation, shared-infrastructure networks, deviations from an account's own behaviour) "
      "with an unsupervised Isolation Forest model over behavioural features. Each rule alert carries a severity, a confidence and "
      "written reasons. Transaction risk (0-100) fuses rule alerts with a capped model contribution, so a model prediction alone "
      "cannot flag a transaction.")
    if run:
        pr = run["params"]
        p(f"Detection run #{run['id']} completed {esc((run['completed_at'] or '')[:19])} UTC. Key parameters: reporting threshold "
          f"${pr.get('reporting_threshold', 0):,.0f}; rapid-movement window {pr.get('rapid_window_hours')} h; velocity "
          f"{pr.get('velocity_min_count')} txns / {pr.get('velocity_window_minutes')} min; dormancy {pr.get('dormant_days')} days; "
          f"flag threshold {pr.get('flag_threshold')}.", "small")
    ind = [a for a in data["automated_indicators"] if a["kind"] == "rule"]
    model = [a for a in data["automated_indicators"] if a["kind"] == "model"]
    p("5a. Automated indicators (rule-based) on subject accounts", "h2")
    if ind:
        rows = [["Indicator", "Severity / conf.", "Summary and reasons", "Review"]]
        for a in ind[:40]:
            rows.append([a["pattern_label"], f"{a['severity']} / {a['confidence']:.2f}",
                         a["title"] + "\n- " + "\n- ".join(a["reasons"]), a["review_status"]])
        s.append(_table(_header_rows(rows, st), [34 * mm, 22 * mm, 108 * mm, 14 * mm], st))
    else:
        p("No rule-based indicators on the subject accounts in the latest detection run.")
    p("5b. Model predictions (statistical anomalies)", "h2")
    p(f"{len(model)} transaction(s) involving subject accounts were ranked by the anomaly model among the most unusual in the dataset. "
      "These are model predictions of statistical unusualness only." if model else "No model anomaly predictions on the subject accounts.")

    img = network_figure(data)
    s.append(KeepTogether([Paragraph("6. Financial flow visualisation", st["h1"]),
                           Image(io.BytesIO(img), width=W * 0.92, height=W * 0.92 * 5.0 / 7.2) if img else Paragraph("No transactions to visualise.", st["body"])]))
    img = timeline_figure(data)
    s.append(KeepTogether([Paragraph("7. Transaction timeline", st["h1"]),
                           Image(io.BytesIO(img), width=W, height=W * 2.6 / 7.2) if img else Paragraph("No transactions.", st["body"])]))
    ev_rows = [["Date (UTC)", "Event", "By"]] + [[e["created_at"][:16].replace("T", " "), e["description"], e["actor"] or "—"] for e in data["case_events"]]
    if len(ev_rows) > 1:
        p("Case activity", "h2")
        s.append(_table(_header_rows(ev_rows, st), [28 * mm, 120 * mm, 30 * mm], st))

    p("8. Supporting evidence references", "h1")
    if data["evidence"]:
        rows = [["Evidence ID", "File / description", "SHA-256", "Integrity", "Custody chain"]]
        for e in data["evidence"]:
            ch = e["custody_chain"]
            rows.append([e["evidence_code"], f"{e['filename']} ({e['category']})\n{e['description'] or ''}", e["sha256"],
                         f"{e['verification_status']}" + (f"\n{e['last_verified_at'][:16]}" if e["last_verified_at"] else ""),
                         f"{'intact' if ch['valid'] else 'BROKEN'} ({ch['events']} events)"])
        s.append(_table(_header_rows(rows, st), [24 * mm, 48 * mm, 58 * mm, 22 * mm, 26 * mm], st))
    else:
        p("No evidence attached.")

    p("9. Investigator observations", "h1")
    if data["investigator_notes"]:
        for n in data["investigator_notes"]:
            p(f"<b>{esc(n['author'])}</b>, {esc(n['created_at'][:16].replace('T', ' '))} UTC:<br/>{esc(n['body']).replace(chr(10), '<br/>')}")
            s.append(Spacer(1, 3))
    else:
        p("No investigator notes recorded.")

    p("10. Automated findings summary", "h1")
    counts = Counter(a["pattern_label"] for a in ind)
    p("Rule-based indicators by type: " + (", ".join(f"{k}: {v}" for k, v in counts.most_common()) or "none") +
      f". Model anomaly predictions: {len(model)}. These summarise automated output only.")

    p("11. Investigator conclusions (findings)", "h1")
    if data["investigator_findings"]:
        for f in data["investigator_findings"]:
            p(f"<b>{esc(f['title'])}</b> - status: <b>{esc(f['status'])}</b> ({esc(f['author'])}, {esc(f['created_at'][:10])})<br/>"
              f"{esc(f['description']).replace(chr(10), '<br/>')}")
            s.append(Spacer(1, 3))
    else:
        p("No findings have been recorded by investigators. No conclusion about wrongdoing is expressed by this report.")

    p("12. Limitations", "h1")
    for line in [
        "Automated indicators are heuristic and parameter-dependent; legitimate activity can match a pattern and illicit activity can evade it.",
        "Anomaly scores measure statistical unusualness relative to the analysed dataset, not intent or legality.",
        "Analysis is limited to the transactions imported into the platform; flows through other institutions or cash are not visible.",
        "Entity relationships shown are suggestions unless explicitly marked as verified by an investigator.",
        "Evidence integrity is attested by SHA-256 hashes recorded at upload and re-verified on demand; it does not attest to the authenticity of the content's origin.",
    ]:
        p("• " + line, "small")
    p(f"Report generated {esc(gen[:19])} UTC.", "small")
    doc.build(s, onFirstPage=on_page, onLaterPages=on_page)
    return buf.getvalue()
